mapper.select:
SELECT U.USERNAME , U.ROLE_CODE , U.DATA_STATUS , U.CREATED_BY , U.CREATED_AT , U.UPDATED_BY , U.UPDATED_AT FROM TB_USER U WHERE TRUE
AND U.USERNAME = #{username}
AND U.ROLE_CODE = #{roleCode}
AND U.DATA_STATUS = #{dataStatus}
ORDER BY U.USERNAME

mapper.insert:
INSERT INTO TB_USER (
    USERNAME
  , PASSWORD
  , ROLE_CODE
  , DATA_STATUS
  , CREATED_BY
  , UPDATED_BY
) VALUES (
    #{username}
  , #{password}
  , #{roleCode}
  , #{dataStatus}
  , #{author}
  , #{author}
)

mapper.update:
UPDATE TB_USER
   SET UPDATED_BY  = #{author}
     , UPDATED_AT  = NOW()

     , DATA_STATUS = #{dataStatus}


     , PASSWORD    = #{password}


     , ROLE_CODE   = #{roleCode}

 WHERE USERNAME    = #{username}
